impl ChannelCheckpointStore {
    /// Discover at most one committed metadata page. Even a retired/non-channel
    /// row advances the cursor, so a large unrelated history cannot force a scan.
    pub(in crate::node) fn discover_step(
        &self,
        repository: &EventRepository,
    ) -> Result<bool, LogError> {
        let after: i64 = self.profile.database().read(|c| {
            self.check_account_on(c)?;
            c.query_row(
                "SELECT ordinal FROM channel_source_scan WHERE singleton=1",
                [],
                |r| r.get(0),
            )
            .map_err(Into::into)
        })?;
        let page = repository.committed_headers_page((after >= 0).then_some(after), 128)?;
        let Some(last) = page.last().map(|row| row.ordinal) else {
            return Ok(false);
        };
        self.profile.database().transaction(|c| {
            self.check_account_on(c)?;
            for row in &page {
                if !row.active {
                    continue;
                }
                let known = row.header.kind == EventKind::MembershipChange
                    || self.has_local_channel_checkpoint_on(c, row.header.conversation)?;
                if known {
                    c.execute(
                        "INSERT OR IGNORE INTO channel_dirty VALUES(?1)",
                        [row.header.conversation.as_bytes().as_slice()],
                    )?;
                    work::queue_discovered_on(c, row.header.conversation, row.ordinal)?;
                }
            }
            if c.execute(
                "UPDATE channel_source_scan SET ordinal=?2 WHERE singleton=1 AND ordinal=?1",
                params![after, last],
            )? != 1
            {
                return Err(LogError::StaleCursor);
            }
            Ok(())
        })?;
        Ok(true)
    }

    /// Compatibility wrapper for callers that use the standard finite turn.
    pub(in crate::node) fn project_step(
