            if c.execute(
                "UPDATE channel_source_scan SET ordinal=?2 WHERE singleton=1 AND ordinal=?1",
                params![after, last],
            )? != 1
            {
                return Err(LogError::StaleCursor);
            }
            Ok(())
        })?;
        Ok(true)
