            })?;
            if changed == 1 {
                selection.persist_with_owner();
            }
            self.pending.set(true);
            Ok(false)
        } else {
            self.save_predicate(&key, None, Some(false))?;
            Ok(false)
        }
    }
    fn pending(&self) -> bool {
